// src/api/axios.js
import axios from "axios";
import { IS_DEMO } from "./demoConfig";
import { BASE_URL } from "./config";

const axios_api = axios.create({
  baseURL: IS_DEMO ? undefined : BASE_URL, // 데모면 baseURL 비움
  headers: { "Content-Type": "application/json" },
});

// 디버깅: 실제 최종 요청 URL 찍기
axios_api.interceptors.request.use(cfg => {
  const qs = cfg.params ? `?${new URLSearchParams(cfg.params)}` : "";
  const full = `${cfg.baseURL || ""}${cfg.url || ""}${qs}`;
  console.log("[REQ]", full);
  return cfg;
});

export default axios_api;
